       "pinyinHtml": "kě shì yǒu shí hòu gōng zuò duō, <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">xiǎng</span> <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">zǎo</span> diǎnr shuì yě bù róng yì. <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">nǐ</span> yǒu shén me hǎo bàn fǎ?",
       "vi": "Nhưng đôi khi việc nhiều, muốn ngủ sớm chút cũng chẳng dễ. Cậu có cách nào hay không?",
