       "pinyinHtml": "wǒ huì xiān bǎ zhòng yào de shì zuò wán, wǎn shàng jǐn liàng shǎo wán shǒu jī, zhēng qǔ àn shí shuì jiào.",
       "vi": "Tớ sẽ ưu tiên làm xong việc quan trọng trước, buổi tối cố gắng ít bấm điện thoại, ráng đi ngủ đúng giờ.",
