       "pinyinHtml": "dāng rán zhòng yào. <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">wǒ</span> xǐ huan qīng dàn yì diǎnr de fàn cài, jǐn liàng shǎo chī tài yóu nì de dōng xi.",
