       "pinyinHtml": "hāi, wǒ kàn dào yì jiā diàn zài mài rén shēn hé gè <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">zhǒng</span> bǔ yào, nǐ píng shí huì mǎi ma?",
       "vi": "Này, tớ thấy có tiệm bán nhân sâm với đủ các loại thuốc bổ, bình thường cậu có hay mua không?",
       "modified": false
