       "role": "B",
       "zh": "那你平时是在家吃得多，还是出去吃得多？",
       "pinyin": "nà nǐ píng shí shì zài jiā chī de duō, hái shì chū qù chī de duō?",
       "pinyinHtml": "nà nǐ píng shí shì zài jiā chī de duō, hái shì chū qù chī de duō?",
       "vi": "Thế ngày thường cậu ăn cơm ở nhà nhiều hơn, hay ra ngoài ăn nhiều hơn?",
       "modified": false
