       "pinyinHtml": "fāng biàn shì fāng biàn, bú guò zài jiā <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">kě</span> yǐ zì jǐ tiáo <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">zhěng</span> kǒu wèi, yě róng yì kòng zhì fàng duō shǎo yóu hé yán.",
       "vi": "Tiện thì tiện thật, nhưng ở nhà mình có thể tự điều chỉnh khẩu vị, lại dễ kiểm soát lượng dầu mỡ và muối nêm vào.",
