       "pinyinHtml": "yǒu dào lǐ. nà rú guǒ jīn tiān wǒ men yì qǐ qù fàn guǎnr, yīng gāi zěn me diǎn cài cái hé shì?",
       "vi": "Có lý lắm. Vậy nếu hôm nay tụi mình cùng ra quán, nên gọi món thế nào cho hợp lý nhỉ?",
