       "pinyinHtml": "wǒ hái méi <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">xiǎng</span> hǎo ne. duì le, nǐ píng shí xǐ huan chī shén me yàng de fàn cài?",
