       "vi": "Khác biệt thật sự không hề nhỏ đâu nha! Khẩu vị miền Bắc thiên về mặn mà vừa vặn, người miền Trung thì ăn cay siêu giỏi, còn miền Nam thì vị hay ngọt hơn một chút.",
       "modified": true,
