       "pinyinHtml": "hǎo shuō! yǒu jī huì lái wǒ jiā, wǒ qīn zì xià chú <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">gěi</span> nǐ lù <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">liǎng</span> shǒu, zuò zhèng zōng de yuè nán chūn juǎn!",
       "vi": "Chuyện nhỏ! Có dịp đến nhà mình, mình đích thân vào bếp trổ tài hai chiêu, làm nem cuốn Việt Nam chính tông cho bạn!",
