       "pinyinHtml": "yào shì <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">mǎi</span> lǐ wù, wǒ hái děi tí qián bǐ jiào jià gé, miǎn de lín shí ná bú dìng zhǔ yì.",
       "vi": "Nếu mà mua quà thì tớ còn phải khảo giá trước, kẻo đến lúc đấy lại phân vân chẳng quyết định được.",
