       "pinyinHtml": "rú guǒ shì xiān yǐ jīng ná dìng zhǔ yì, <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">kě</span> <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">yǐ</span> mǎi; bù rán zuì hǎo xiān lěng jìng yí xià.",
