       "pinyinHtml": "tīng qǐ lái tǐng qīng sōng. <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">nǐ</span> xǐ huan chū qù lǚ xíng, hái shì dài zài jiā lǐ?",
