       "role": "B",
       "zh": "看假期长短吧。假期短的时候，我喜欢在家做饭、看书、陪家人。",
       "pinyin": "kàn jià qī cháng duǎn ba. jià qī duǎn de shí hòu, wǒ xǐ huan zài jiā zuò fàn, kàn shū, péi jiā rén.",
       "pinyinHtml": "kàn jià qī cháng duǎn ba. jià qī duǎn de shí hòu, <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">wǒ</span> xǐ huan zài jiā zuò fàn, kàn shū, péi jiā rén.",
       "vi": "Cũng tùy vào kỳ nghỉ dài hay ngắn nữa. Đợt nghỉ ngắn thì tớ thích ở nhà nấu nướng, đọc sách và quây quần bên gia đình."
