       "pinyinHtml": "nǐ zhào zhè ge bàn fǎ shì shì kàn, xīn <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">lǐ</span> zhǔn néng tà shí hěn duō, gān qǐ huó lái yě gèng yǒu jìnr.",
