       "pinyinHtml": "yǐ qián huì. hòu lái fā xiàn, yì yǒu lín shí rèn wu, zhěng gè rì chéng jiù luàn le.",
       "vi": "Hồi trước thì có đấy. Về sau mới vỡ lẽ ra là, hễ đột xuất có nhiệm vụ phát sinh là cả cái lịch trình rối tung rối mù lên ngay."
