       "pinyinHtml": "wǒ xiān zuò zuì zháo jí de shì, zài lì yòng líng suì shí jiān fù xí, hái qǔ xiāo le yí gè bú tài zhòng yào de ān pái.",
       "vi": "Tớ giải quyết việc gấp nhất trước, sau đó tận dụng các khoảng thời gian vụn vặt để ôn bài, rồi còn hủy bớt một cái hẹn không quá quan trọng nữa."
