       "pinyinHtml": "tīng qǐ lái <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">nǐ</span> <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">bǐ</span> yǐ qián yǒu jīng yàn duō le. kě shì zhè me máng, <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">nǐ</span> zěn me bǎo zhèng xiū xi ne?",
