       "pinyinHtml": "wǒ yì bān xiān liè gòu wù qīng dān. xià cì wǒ men <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">kě</span> yǐ hù xiāng tí xǐng, bié mǎi méi yòng de dōng xi.",
