       "pinyinHtml": "rú <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">guǒ</span> nǐ kàn dào yì shuāng <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">hěn</span> xǐ huan de xié <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">dǎ</span> wǔ zhé, dàn zhè ge yuè yù suàn bú gòu, <span class=\"t3\" title=\"Biến điệu thanh 3: tự đọc thành thanh 2\">nǐ</span> zěn me bàn?",
